create function public.log_deal(_deal uuid,_body text) returns void language sql security definer set search_path=public as $$insert into public.deal_events(deal_id,author_id,kind,body) values(_deal,auth.uid(),'system',_body)$$;
revoke execute on function public.log_deal(uuid,text) from public,anon,authenticated;
create function public.open_deal(_listing uuid,_buyer uuid,_amount numeric,_offer uuid) returns uuid language plpgsql security definer set search_path=public as $$declare l public.listings; did uuid; rate numeric; begin select * into l from public.listings where id=_listing for update; if l.id is null or l.status<>'approved' or l.seller_id is null or _buyer=l.seller_id then raise exception 'Listing not available'; end if; select commission_rate into rate from public.site_settings where id=1; insert into public.deals(listing_id,buyer_id,seller_id,offer_id,amount,commission) values(_listing,_buyer,l.seller_id,_offer,_amount,round(_amount*coalesce(rate,.10),2)) returning id into did; update public.listings set status='in_progress',updated_at=now() where id=_listing; update public.offers set status='rejected',updated_at=now() where listing_id=_listing and status='pending' and id is distinct from _offer; perform public.log_deal(did,'Deal opened. Submit payment only to receiving details shown in this room.'); return did; end$$;
revoke execute on function public.open_deal(uuid,uuid,numeric,uuid) from public,anon,authenticated;
create function public.make_offer(_listing uuid,_amount numeric,_message text) returns uuid language plpgsql security definer set search_path=public as $$declare l public.listings; oid uuid; begin if auth.uid() is null then raise exception 'Sign in required'; end if; select * into l from public.listings where id=_listing for update; if l.id is null or l.status<>'approved' or l.seller_id is null or l.sale_type<>'fixed' then raise exception 'Listing not available for offers'; end if; if l.seller_id=auth.uid() then raise exception 'You cannot offer on your own listing'; end if; if _amount is null or _amount<=0 then raise exception 'Invalid amount'; end if; insert into public.offers(listing_id,buyer_id,amount,message) values(_listing,auth.uid(),_amount,left(_message,1000)) returning id into oid; return oid; end$$;
create function public.buy_now(_listing uuid) returns uuid language plpgsql security definer set search_path=public as $$declare l public.listings; begin if auth.uid() is null then raise exception 'Sign in required'; end if; select * into l from public.listings where id=_listing for update; if l.id is null or l.status<>'approved' or l.sale_type<>'fixed' or l.seller_id is null then raise exception 'Listing not available'; end if; if l.seller_id=auth.uid() then raise exception 'You cannot buy your own listing'; end if; return public.open_deal(_listing,auth.uid(),l.price,null); end$$;
create function public.respond_offer(_offer uuid,_accept boolean) returns uuid language plpgsql security definer set search_path=public as $$declare o public.offers; l public.listings; begin if auth.uid() is null then raise exception 'Sign in required'; end if; select * into o from public.offers where id=_offer for update; select * into l from public.listings where id=o.listing_id for update; if o.id is null or l.seller_id is distinct from auth.uid() or o.status<>'pending' or l.status<>'approved' then raise exception 'Offer not available'; end if; if not _accept then update public.offers set status='rejected',updated_at=now() where id=_offer; return null; end if; update public.offers set status='accepted',updated_at=now() where id=_offer; return public.open_deal(o.listing_id,o.buyer_id,o.amount,o.id); end$$;
create function public.withdraw_offer(_offer uuid) returns void language plpgsql security definer set search_path=public as $$begin if auth.uid() is null then raise exception 'Sign in required'; end if; update public.offers set status='withdrawn',updated_at=now() where id=_offer and buyer_id=auth.uid() and status='pending'; if not found then raise exception 'Offer not available'; end if; end$$;
create function public.place_bid(_listing uuid,_amount numeric) returns uuid language plpgsql security definer set search_path=public as $$declare l public.listings; highest numeric; bid_id uuid; begin if auth.uid() is null then raise exception 'Sign in required'; end if; select * into l from public.listings where id=_listing for update; if l.id is null or l.status<>'approved' or l.sale_type<>'auction' or l.seller_id is null or l.ends_at is null or l.ends_at<=now() then raise exception 'Auction is not open'; end if; if l.seller_id=auth.uid() then raise exception 'You cannot bid on your own auction'; end if; select max(amount) into highest from public.bids where listing_id=_listing; if _amount is null or _amount<l.price or (highest is not null and _amount<=highest) then raise exception 'Bid must meet the starting price and exceed the highest bid'; end if; insert into public.bids(listing_id,buyer_id,amount) values(_listing,auth.uid(),_amount) returning id into bid_id; return bid_id; end$$;
create function public.finalize_auction(_listing uuid) returns uuid language plpgsql security definer set search_path=public as $$declare l public.listings; winner public.bids; begin if auth.uid() is null then raise exception 'Sign in required'; end if; select * into l from public.listings where id=_listing for update; if l.id is null or l.sale_type<>'auction' or l.status<>'approved' or l.ends_at is null or l.ends_at>now() then raise exception 'Auction has not ended or is already closed'; end if; select * into winner from public.bids where listing_id=_listing order by amount desc,created_at asc limit 1; if l.seller_id is distinct from auth.uid() and winner.buyer_id is distinct from auth.uid() and not public.has_role(auth.uid(),'admin') then raise exception 'Not permitted'; end if; if winner.id is null then raise exception 'No bids received'; end if; return public.open_deal(_listing,winner.buyer_id,winner.amount,null); end$$;
create function public.auction_summary(_listing uuid) returns table(highest_bid numeric,bid_count bigint) language sql stable security definer set search_path=public as $$select max(b.amount),count(*) from public.bids b join public.listings l on l.id=b.listing_id where l.id=_listing and l.status in ('approved','in_progress','sold')$$;
grant execute on function public.auction_summary(uuid) to anon,authenticated;
create function public.moderate_listing(_listing uuid,_status public.listing_status,_note text,_verified text[],_featured boolean) returns void language plpgsql security definer set search_path=public as $$begin if auth.uid() is null or not public.has_role(auth.uid(),'admin') then raise exception 'Admin access required'; end if; if _status not in ('approved','rejected','suspended') then raise exception 'Invalid moderation status'; end if; update public.listings set status=_status,verified=coalesce(_verified,'{}'),featured=_featured,updated_at=now() where id=_listing and status not in ('in_progress','sold'); if not found then raise exception 'Listing not available'; end if; insert into public.listing_reviews(listing_id,admin_note) values(_listing,left(_note,4000)) on conflict(listing_id) do update set admin_note=excluded.admin_note,updated_at=now(); end$$;
create function public.deal_payment_settings(_deal uuid) returns public.payment_settings language plpgsql stable security definer set search_path=public as $$declare d public.deals; s public.payment_settings; begin if auth.uid() is null then raise exception 'Sign in required'; end if; select * into d from public.deals where id=_deal; if d.id is null or (d.buyer_id is distinct from auth.uid() and d.seller_id is distinct from auth.uid() and not public.has_role(auth.uid(),'admin')) then raise exception 'Not permitted'; end if; select * into s from public.payment_settings where id=1; return s; end$$;
create function public.deal_action(_deal uuid,_action text,_text1 text default null,_text2 text default null) returns void language plpgsql security definer set search_path=public as $$declare d public.deals; uid uuid:=auth.uid(); is_admin boolean:=public.has_role(auth.uid(),'admin'); begin if uid is null then raise exception 'Sign in required'; end if; select * into d from public.deals where id=_deal for update; if d.id is null or not(d.buyer_id=uid or d.seller_id=uid or is_admin) then raise exception 'Deal not found'; end if;
if _action='submit_payment' then
if d.buyer_id<>uid or d.stage<>'agreement' then raise exception 'Not allowed at this stage'; end if;
if coalesce(trim(_text1),'')='' or _text2 is null or _text2 not in ('binance_pay','usdt_trc20','usdt_bep20') then raise exception 'Transaction ID and method required'; end if;
if not exists(select 1 from public.payment_settings where id=1 and case _text2 when 'binance_pay' then binance_pay_id when 'usdt_trc20' then usdt_trc20_address else usdt_bep20_address end<>'') then raise exception 'Receiving details are not configured'; end if;
if not exists(select 1 from public.deal_files where deal_id=_deal and uploader_id=uid and kind='payment') then raise exception 'Upload payment proof first'; end if;
update public.deals set stage='payment_submitted',payment_txid=trim(_text1),payment_method=_text2,updated_at=now() where id=_deal;
elsif _action='verify_payment' then
if not is_admin or d.stage<>'payment_submitted' then raise exception 'Not allowed at this stage'; end if; update public.deals set stage='payment_verified',updated_at=now() where id=_deal;
elsif _action='reject_payment' then
if not is_admin or d.stage<>'payment_submitted' or coalesce(trim(_text1),'')='' then raise exception 'Admin rejection reason required'; end if; update public.deals set stage='agreement',payment_note=_text1,payment_txid=null,updated_at=now() where id=_deal;
elsif _action='start_transfer' then
if d.seller_id<>uid or d.stage<>'payment_verified' then raise exception 'Not allowed at this stage'; end if; update public.deals set stage='transferring',updated_at=now() where id=_deal;
elsif _action='mark_delivered' then
if d.seller_id<>uid or d.stage not in ('payment_verified','transferring') or coalesce(trim(_text1),'')='' then raise exception 'Delivery notes required at this stage'; end if; update public.deals set stage='delivered',transfer_notes=left(_text1,4000),updated_at=now() where id=_deal;
elsif _action='approve' then
if d.buyer_id<>uid or d.stage<>'delivered' then raise exception 'Only the buyer can approve delivery'; end if; update public.deals set stage='completed',updated_at=now() where id=_deal; update public.listings set status='sold',updated_at=now() where id=d.listing_id;
elsif _action='dispute' then
if not(d.buyer_id=uid or d.seller_id=uid) or d.stage not in ('payment_verified','transferring','delivered') or coalesce(trim(_text1),'')='' then raise exception 'Dispute reason required at this stage'; end if; update public.deals set stage='disputed',dispute_reason=left(_text1,2000),updated_at=now() where id=_deal;
elsif _action='resolve_complete' then
if not is_admin or d.stage<>'disputed' or coalesce(trim(_text1),'')='' then raise exception 'Admin resolution note required'; end if; update public.deals set stage='completed',updated_at=now() where id=_deal; update public.listings set status='sold',updated_at=now() where id=d.listing_id;
elsif _action='resolve_refund' then
if not is_admin or d.stage<>'disputed' or coalesce(trim(_text1),'')='' then raise exception 'Refund transaction reference required'; end if; update public.deals set stage='refunded',payout_reference=_text1,updated_at=now() where id=_deal; update public.listings set status='approved',updated_at=now() where id=d.listing_id;
elsif _action='cancel' then
if d.stage<>'agreement' then raise exception 'Only unpaid agreements can be cancelled'; end if; update public.deals set stage='cancelled',updated_at=now() where id=_deal; update public.listings set status='approved',updated_at=now() where id=d.listing_id;
elsif _action='mark_paid' then
if not is_admin or d.stage<>'completed' or d.payout_paid_at is not null or coalesce(trim(_text1),'')='' then raise exception 'Completed deal and new payout reference required'; end if; update public.deals set payout_reference=trim(_text1),payout_paid_at=now(),updated_at=now() where id=_deal;
else raise exception 'Unknown action'; end if;
perform public.log_deal(_deal,replace(_action,'_',' ')||case when _action in ('reject_payment','mark_delivered','dispute','resolve_complete','resolve_refund','mark_paid') then ': '||coalesce(_text1,'') else '' end);
end$$;
revoke execute on function public.make_offer(uuid,numeric,text),public.buy_now(uuid),public.respond_offer(uuid,boolean),public.withdraw_offer(uuid),public.place_bid(uuid,numeric),public.finalize_auction(uuid),public.moderate_listing(uuid,public.listing_status,text,text[],boolean),public.deal_payment_settings(uuid),public.deal_action(uuid,text,text,text) from public,anon;
grant execute on function public.make_offer(uuid,numeric,text),public.buy_now(uuid),public.respond_offer(uuid,boolean),public.withdraw_offer(uuid),public.place_bid(uuid,numeric),public.finalize_auction(uuid),public.moderate_listing(uuid,public.listing_status,text,text[],boolean),public.deal_payment_settings(uuid),public.deal_action(uuid,text,text,text) to authenticated;
create policy listing_image_read on storage.objects for select to anon,authenticated using(bucket_id='listing-images' and (exists(select 1 from public.listings l where name=any(l.images) and l.status in ('approved','in_progress','sold')) or (select auth.uid())::text=(storage.foldername(name))[1]));
create policy listing_image_upload on storage.objects for insert to authenticated with check(bucket_id='listing-images' and (storage.foldername(name))[1]=auth.uid()::text and lower(storage.extension(name)) in ('jpg','jpeg','png','webp'));
create policy listing_image_delete on storage.objects for delete to authenticated using(bucket_id='listing-images' and (storage.foldername(name))[1]=auth.uid()::text and not exists(select 1 from public.listings l where name=any(l.images) and l.status in ('approved','in_progress','sold')));
create policy evidence_read on storage.objects for select to authenticated using(bucket_id='deal-evidence' and exists(select 1 from public.deals d where d.id::text=(storage.foldername(name))[1] and (d.buyer_id=auth.uid() or d.seller_id=auth.uid() or public.has_role(auth.uid(),'admin'))));
create policy evidence_upload on storage.objects for insert to authenticated with check(bucket_id='deal-evidence' and (storage.foldername(name))[2]=auth.uid()::text and exists(select 1 from public.deals d where d.id::text=(storage.foldername(name))[1] and (d.buyer_id=auth.uid() or d.seller_id=auth.uid() or public.has_role(auth.uid(),'admin'))));
alter publication supabase_realtime add table public.deal_events;
create function public.update_ownership(_listing uuid,_method text,_evidence text) returns void language plpgsql security definer set search_path=public as $$begin if auth.uid() is null or _method not in ('dns','meta','email','analytics') or length(trim(_evidence))<5 then raise exception 'Valid ownership evidence required'; end if; if not exists(select 1 from public.listings where id=_listing and seller_id=auth.uid() and status in ('draft','pending','rejected')) then raise exception 'Listing is not editable'; end if; update public.listing_reviews set ownership_method=_method,ownership_evidence=left(_evidence,4000),updated_at=now() where listing_id=_listing; end$$; revoke execute on function public.update_ownership(uuid,text,text) from public,anon; grant execute on function public.update_ownership(uuid,text,text) to authenticated;
create table public.seller_reviews(id uuid primary key default gen_random_uuid(),deal_id uuid not null unique references public.deals(id),reviewer_id uuid not null references public.profiles(id),seller_id uuid not null references public.profiles(id),rating int not null check(rating between 1 and 5),body text not null check(length(body) between 5 and 2000),created_at timestamptz not null default now()); grant select on public.seller_reviews to anon,authenticated; grant insert(deal_id,reviewer_id,seller_id,rating,body) on public.seller_reviews to authenticated; grant all on public.seller_reviews to service_role; alter table public.seller_reviews enable row level security; create policy seller_reviews_public on public.seller_reviews for select to anon,authenticated using(true); create policy buyer_completed_review on public.seller_reviews for insert to authenticated with check(reviewer_id=auth.uid() and exists(select 1 from public.deals d where d.id=deal_id and d.buyer_id=auth.uid() and d.seller_id=seller_reviews.seller_id and d.stage='completed')); create index seller_review_profile on public.seller_reviews(seller_id); create function public.seller_summary(_seller uuid) returns table(rating numeric,reviews bigint,deals bigint) language sql stable security definer set search_path=public as $$select (select round(avg(r.rating),1) from public.seller_reviews r where r.seller_id=_seller),(select count(*) from public.seller_reviews r where r.seller_id=_seller),(select count(*) from public.deals d where d.seller_id=_seller and d.stage='completed')$$; revoke execute on function public.seller_summary(uuid) from public; grant execute on function public.seller_summary(uuid) to anon,authenticated;